# Each cell is isolated - rebuild everything in one block
from itertools import combinations, permutations
from collections import defaultdict, deque
from pysat.solvers import Glucose3
from pysat.formula import CNF
from pysat.card import CardEnc, EncType

n = 25
edges_list = [(u, v) for u in range(n) for v in range(u+1, n)]
edge_idx = {e: i+1 for i, e in enumerate(edges_list)}

def evar(u, v):
    return edge_idx[(min(u,v), max(u,v))]

cnf = CNF()

for v in range(n):
    incident = [evar(min(u,v), max(u,v)) for u in range(n) if u != v]
    cnf.extend(CardEnc.atleast(lits=incident, bound=3, encoding=EncType.seqcounter).clauses)
    cnf.extend(CardEnc.atmost(lits=incident, bound=5, encoding=EncType.seqcounter).clauses)

for a, b, c in combinations(range(n), 3):
    cnf.append([-evar(a,b), -evar(b,c), -evar(a,c)])

for combo in combinations(range(n), 4):
    a, b, c, d = combo
    for cyc in [(a,b,c,d),(a,b,d,c),(a,c,b,d)]:
        x,y,z,w = cyc
        cnf.append([-evar(x,y), -evar(y,z), -evar(z,w), -evar(w,x)])

for combo in combinations(range(n), 5):
    verts = list(combo)
    seen = set()
    for perm in permutations(verts):
        min_idx = perm.index(min(perm))
        rotated = perm[min_idx:] + perm[:min_idx]
        if rotated[1] > rotated[-1]:
            rotated = (rotated[0],) + rotated[1:][::-1]
        rotated = tuple(rotated)
        if rotated not in seen:
            seen.add(rotated)
            a,b,c,d,e = rotated
            cnf.append([-evar(a,b), -evar(b,c), -evar(c,d), -evar(d,e), -evar(e,a)])

print(f"Total clauses: {len(cnf.clauses)}")
print("Solving...")

solver = Glucose3()
for clause in cnf.clauses:
    solver.add_clause(clause)

sat = solver.solve()
print(f"SAT: {sat}")

if sat:
    model = solver.get_model()
    sol_edges = [(u,v) for (u,v) in edges_list if model[edge_idx[(u,v)]-1] > 0]
    print(f"Edges: {len(sol_edges)}")

    deg = defaultdict(int)
    for u,v in sol_edges:
        deg[u] += 1; deg[v] += 1
    print(f"Degrees: min={min(deg.values())}, max={max(deg.values())}")

    adj = defaultdict(set)
    for u,v in sol_edges:
        adj[u].add(v); adj[v].add(u)

    def bfs_girth(start):
        dist = {start: 0}
        parent = {start: -1}
        q = deque([start])
        mc = float('inf')
        while q:
            u = q.popleft()
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u]+1; parent[w] = u; q.append(w)
                elif parent[u] != w:
                    mc = min(mc, dist[u]+dist[w]+1)
        return mc

    girth = min(bfs_girth(v) for v in range(n))
    print(f"Girth: {girth}")
    if girth >= 7:
        print("SUCCESS!")
        print(sol_edges)

