# McGee graph: LCF notation [12, 7, -7]^8
# LCF notation: start with a cycle 0-1-2-...-23-0
# Then add chords: from vertex i, connect to i+chord[i%len(chords)] mod n

def lcf_graph(n, chords):
    edges = set()
    # Cycle edges
    for i in range(n):
        u, v = i, (i+1) % n
        edges.add((min(u,v), max(u,v)))
    # Chord edges
    for i in range(n):
        chord = chords[i % len(chords)]
        j = (i + chord) % n
        if i != j:
            edges.add((min(i,j), max(i,j)))
    return list(edges)

